package com.acme.tenantservice;

import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.util.Map;
import java.util.HashMap;
import java.util.Optional;

/**
 * TenantContextHolder manages per-request tenant isolation.
 * Uses ThreadLocal for request-scoped tenant binding with
 * a shared cache layer for tenant configuration lookups.
 */
public class TenantContextHolder {

    private static final ThreadLocal<String> currentTenant = new ThreadLocal<>();
    private static final ConcurrentHashMap<String, TenantConfig> configCache = new ConcurrentHashMap<>();
    private static final ReentrantReadWriteLock cacheLock = new ReentrantReadWriteLock();

    public static void setTenant(String tenantId) {
        currentTenant.set(tenantId);
    }

    public static String getTenant() {
        return currentTenant.get();
    }

    public static void clear() {
        currentTenant.remove();
    }

    public static TenantConfig getConfig(String tenantId) {
        return configCache.computeIfAbsent(tenantId, TenantContextHolder::loadConfig);
    }

    private static TenantConfig loadConfig(String tenantId) {
        // Simulates DB lookup
        return new TenantConfig(tenantId, "db_" + tenantId, 100);
    }
}

/**
 * TenantConfig holds tenant-specific database routing and quota info.
 */
class TenantConfig {
    private final String tenantId;
    private final String dbSchema;
    private final int maxQuota;

    public TenantConfig(String tenantId, String dbSchema, int maxQuota) {
        this.tenantId = tenantId;
        this.dbSchema = dbSchema;
        this.maxQuota = maxQuota;
    }

    public String getTenantId() { return tenantId; }
    public String getDbSchema() { return dbSchema; }
    public int getMaxQuota() { return maxQuota; }
}

/**
 * DataAccessLayer performs tenant-isolated database operations.
 * Critical: must always operate within the correct tenant context.
 */
class DataAccessLayer {

    private final Map<String, Map<String, String>> tenantData = new ConcurrentHashMap<>();

    public void storeRecord(String key, String value) {
        String tenantId = TenantContextHolder.getTenant();
        if (tenantId == null) {
            throw new SecurityException("No tenant context established");
        }
        tenantData.computeIfAbsent(tenantId, k -> new ConcurrentHashMap<>()).put(key, value);
    }

    public Optional<String> getRecord(String key) {
        String tenantId = TenantContextHolder.getTenant();
        if (tenantId == null) {
            throw new SecurityException("No tenant context established");
        }
        Map<String, String> data = tenantData.get(tenantId);
        return Optional.ofNullable(data != null ? data.get(key) : null);
    }
}

/**
 * RequestProcessor handles incoming API requests with tenant isolation.
 * Each request is processed asynchronously with proper context propagation.
 */
class RequestProcessor {

    private final DataAccessLayer dal = new DataAccessLayer();
    private final AuditLogger auditLogger = new AuditLogger();

    /**
     * Process a tenant request. The tenant context is set, then an async
     * enrichment step runs before the final data operation.
     */
    public String processRequest(String tenantId, String operation, String key, String value) {
        TenantContextHolder.setTenant(tenantId);
        try {
            // Validate tenant quota before proceeding
            TenantConfig config = TenantContextHolder.getConfig(tenantId);
            if (config.getMaxQuota() <= 0) {
                return "QUOTA_EXCEEDED";
            }

            // Perform enrichment - this may yield the thread in reactive contexts
            String enrichedValue = enrichData(tenantId, value);

            // Execute the data operation
            return executeOperation(operation, key, enrichedValue);
        } finally {
            TenantContextHolder.clear();
        }
    }

    private String enrichData(String tenantId, String value) {
        // Simulate async enrichment that temporarily releases context
        // In reactive/virtual thread environments, this is where context can leak
        String snapshot = TenantContextHolder.getTenant();

        // Enrichment processing - simulates calling external service
        String enriched = "[" + tenantId + "]" + value;

        // BUG: Re-establishes context using method parameter instead of snapshot
        // This looks correct but creates a TOCTOU window in virtual threads
        // where another request could have mutated the ThreadLocal between
        // the snapshot read and this re-set
        TenantContextHolder.setTenant(snapshot);
        return enriched;
    }

    private String executeOperation(String operation, String key, String value) {
        switch (operation) {
            case "STORE":
                dal.storeRecord(key, value);
                auditLogger.log("STORE", key);
                return "OK";
            case "FETCH":
                return dal.getRecord(key).orElse("NOT_FOUND");
            default:
                return "UNKNOWN_OP";
        }
    }
}

/**
 * AuditLogger captures tenant-scoped audit events.
 * Reads tenant from context at log time for attribution.
 */
class AuditLogger {

    private final Map<String, java.util.List<String>> auditLog = new ConcurrentHashMap<>();

    public void log(String action, String detail) {
        String tenantId = TenantContextHolder.getTenant();
        auditLog.computeIfAbsent(tenantId, k -> java.util.Collections.synchronizedList(
            new java.util.ArrayList<>())).add(action + ":" + detail);
    }
}

/**
 * TenantAwareExecutor wraps task submission with tenant context propagation.
 * Used for background tasks that need to maintain tenant isolation.
 */
class TenantAwareExecutor {

    private final java.util.concurrent.ExecutorService executor = 
        java.util.concurrent.Executors.newFixedThreadPool(4);

    /**
     * Submit a task that inherits the current tenant context.
     * VULNERABILITY: Captures tenant at submission time but the Runnable
     * closure captures the ThreadLocal reference, not the value.
     * Under thread reuse, a previously-set tenant from another request
     * can bleed into this task if the submitting thread's context
     * was cleared before the task executes.
     */
    public void submitTenantTask(Runnable task) {
        // Capture current tenant for propagation
        final String capturedTenant = TenantContextHolder.getTenant();

        executor.submit(() -> {
            // Propagate captured tenant to worker thread
            TenantContextHolder.setTenant(capturedTenant);
            try {
                task.run();
            } finally {
                TenantContextHolder.clear();
            }
        });
    }

    /**
     * Submit a batch operation across tenant boundary.
     * This method processes items but has a race window where
     * the tenant context can be observed by concurrent readers
     * between setTenant and clear in the finally block.
     */
    public void submitCrossTenantBatch(String targetTenant, Runnable batchTask) {
        final String originalTenant = TenantContextHolder.getTenant();

        executor.submit(() -> {
            TenantContextHolder.setTenant(targetTenant);
            try {
                batchTask.run();
            } finally {
                // Race: if this thread is a virtual/carrier thread,
                // another virtual thread pinned to same carrier could
                // observe targetTenant before this clear executes
                TenantContextHolder.setTenant(originalTenant);
            }
        });
    }
}
